descriptions.zh:
本接口与[PutDcdnKv](~~PutDcdnKv~~)的功能一样，只是允许上传更大请求体。当请求体较小时推荐直接使用[PutDcdnKv](~~PutDcdnKv~~)接口，从而减少服务端处理时间。本接口需要使用SDK进行调用。以golang SDK为例，需要使用PutDcdnKvWithHighCapacityAdvance函数进行调用。
```
func TestPutDcdnKvWithHighCapacity() {
	// 配置初始化
	cfg := new(openapi.Config)
	cfg.SetAccessKeyId("xxxxxxxxx")
	cfg.SetAccessKeySecret("xxxxxxxxxx")
	cli, err := NewClient(cfg)
	if err != nil {
		return err
	}
	runtime := &util.RuntimeOptions{}

	// 构造待上传的键值对请求
	namespace := "test-put-kv"
	key := "test_PutDcdnKvWithHighCapacity_0"
	value := strings.Repeat("t", 10*1024*1024)
	rawReq := &PutDcdnKvRequest{
		Namespace: &namespace,
		Key:       &key,
		Value:     &value,
	}
	payload, err := json.Marshal(rawReq)
	if err != nil {
		return err
	}

	// 如果payload大于2M，则调用大容量接口进行上传
	reqHighCapacity := &PutDcdnKvWithHighCapacityAdvanceRequest{
		Namespace: &namespace,
		Key:       &key,
		UrlObject: bytes.NewReader([]byte(payload)),
	}

	resp, err := cli.PutDcdnKvWithHighCapacityAdvance(reqHighCapacity, runtime)
	if err != nil {
		return err
	}
	return nil
}

descriptions.en:
This operation provides the same functionality as [PutDcdnKv](~~PutDcdnKv~~) but supports a larger request body. If the request body is small, use the [PutDcdnKv](~~PutDcdnKv~~) operation to reduce the server-side processing time. Calling this operation requires an SDK. For example, if you use the Go SDK, call the PutDcdnKvWithHighCapacityAdvance function.

```
func TestPutDcdnKvWithHighCapacity() {
	// Initialize the configuration.
	cfg := new(openapi.Config)
	cfg.SetAccessKeyId("xxxxxxxxx")
	cfg.SetAccessKeySecret("xxxxxxxxxx")
	cli, err := NewClient(cfg)
	if err != nil {
		return err
	}
	runtime := &util.RuntimeOptions{}

	// Construct the key-value pair request to upload.
	namespace := "test-put-kv"
	key := "test_PutDcdnKvWithHighCapacity_0"
	value := strings.Repeat("t", 10*1024*1024)
	rawReq := &PutDcdnKvRequest{
		Namespace: &namespace,
		Key:       &key,
		Value:     &value,
	}
	payload, err := json.Marshal(rawReq)
	if err != nil {
		return err
	}

	// If the payload is larger than 2 MB, call the high-capacity operation to upload the data.
	reqHighCapacity := &PutDcdnKvWithHighCapacityAdvanceRequest{
		Namespace: &namespace,
		Key:       &key,
		UrlObject: bytes.NewReader([]byte(payload)),
	}

	resp, err := cli.PutDcdnKvWithHighCapacityAdvance(reqHighCapacity, runtime)
	if err != nil {
		return err
	}
	return nil
}
```
